48: async function request(path, options, fetchImpl) {
49:   let response;
50:   try {
51:     response = await fetchImpl(`${API}${path}`, { ...options, signal: AbortSignal.timeout(120_000) });
52:   } catch (error) {
53:     throw new Error(`OpenRouter unavailable (${error.cause?.code ?? error.name}). No retry was made.`);
54:   }
55:   if (!response.ok) throw new Error(`OpenRouter HTTP ${response.status}. No retry was made.`);
56:   return response.json();
57: }
