79: export async function plan(objective, directory, {
80:   apiKey = process.env.OPENROUTER_API_KEY,
81:   fetchImpl = fetch,
82:   graphPath = join(directory, 'graph', 'graph.json'),
83: } = {}) {
84:   if (typeof objective !== 'string' || !objective.trim()) throw new Error('An objective is required.');
85:   if (!apiKey) throw new Error('Set OPENROUTER_API_KEY before planning.');
86:   const outcomes = await priorGraph(graphPath);
87:   const prior = outcomes?.length ? outcomes : null;
88:   const investigate = await repositoryTools(directory);
89:   const output = join(directory, '.tag');
90:   try {
91:     await mkdir(output, { mode: 0o700 });
92:   } catch (error) {
93:     if (error.code === 'EEXIST') throw new Error('.tag already exists. Preserve or move it before starting another experiment.');
94:     throw error;
95:   }
96:   await writeFile(join(output, '.gitignore'), '*\n', { flag: 'wx', mode: 0o600 });
97:   // A failed run is an experimental result: keep what it did and what it answered.
98:   const attempt = { model: MODEL, createdAt: new Date().toISOString(), requests: 0, costUsd: 0, investigation: [] };
99:   let keep = false;
100:   try {
101:     const { data } = await request('/models', {}, fetchImpl);
102:     const model = data?.find(item => item.id === MODEL);
103:     const promptPrice = Number(model?.pricing?.prompt);
104:     const completionPrice = Number(model?.pricing?.completion);
105:     // Deliberately conservative caps, not a general-purpose cost reservation system.
106:     if (!model || !Number.isFinite(promptPrice) || promptPrice < 0 || promptPrice > 0.5 / 1e6
107:       || !Number.isFinite(completionPrice) || completionPrice < 0 || completionPrice > 1.5 / 1e6
108:       || Number(model.pricing.request ?? 0) !== 0) {
109:       throw new Error('Model unavailable or pricing exceeds the seed’s budget caps. Human review required.');
110:     }
111:     const messages = [
112:       { role: 'system', content: instructions },
113:       { role: 'user', content: objective },
114:     ];
115:     attempt.priorGraph = prior ? graphPath : null;
116:     let supplied = false;
117:     const investigation = attempt.investigation;
118:     const researched = () => investigation.some(item => item.tool === 'read_file' && /^\d+: /.test(item.result));
119:     for (let turn = 1; turn <= MAX_REQUESTS; turn++) {
120:       attempt.requests = turn;
121:       // Supplied with the graph up front, a real run answered with the graph: it restated three
122:       // of its four nodes verbatim, read nothing, and cited files it had never opened. The
123:       // durable state is real input, so it is withheld until the repository has actually been
124:       // investigated, and never allowed to stand in for investigating it.
125:       if (prior && !supplied && researched()) {
126:         supplied = true;
127:         messages.push({ role: 'user', content: `Work already performed on this objective, recorded by a human after observing what each attempt actually did:\n${prior.join('\n')}\nThis list is not a plan and is not exhaustive. Continue investigating if you have not finished. These outcomes are not repository evidence: do not cite them, or any path mentioned in them, unless you have read that file yourself in this investigation.` });
128:       }
129:       const body = {
130:         model: MODEL, messages, tools, max_tokens: MAX_OUTPUT,
131:         tool_choice: turn === MAX_REQUESTS ? 'none' : 'auto',
132:         temperature: 0.2,
133:         provider: { max_price: { prompt: 0.5, completion: 1.5 } },
134:       };
135:       if (Buffer.byteLength(JSON.stringify(body)) > MAX_CONTEXT_BYTES) {
136:         throw new Error('Research context limit reached. No graph saved; human review required.');
137:       }
138:       const response = await request('/chat/completions', {
139:         method: 'POST',
140:         headers: { Authorization: 'Bearer ' + apiKey, 'Content-Type': 'application/json' },
141:         body: JSON.stringify(body),
142:       }, fetchImpl);
143:       const cost = response.usage?.cost;
144:       attempt.costUsd = attempt.costUsd !== null && typeof cost === 'number' && Number.isFinite(cost) && cost >= 0
145:         ? attempt.costUsd + cost : null;
146:       const choice = response.choices?.[0];
147:       const message = choice?.message;
148:       if (!message || choice.finish_reason === 'length' || response.error) {
149:         throw new Error('The model returned an error or incomplete answer. No retry was made.');
150:       }
151:       if (message.tool_calls?.length) {
152:         if (turn === MAX_REQUESTS || message.tool_calls.length > 12) throw new Error('Investigation limit reached.');
153:         messages.push({ role: 'assistant', content: message.content ?? null, tool_calls: message.tool_calls });
154:         for (const call of message.tool_calls) {
155:           let args;
156:           let result;
157:           try {
158:             args = JSON.parse(call.function.arguments);
159:             result = await investigate(call.function.name, args);
160:           } catch {
161:             // Do not return raw filesystem errors or other environment details to the model.
162:             result = 'Tool unavailable or invalid arguments. Use listed tracked text files and the documented tool parameters.';
163:           }
164:           investigation.push({ tool: call.function.name, arguments: args ?? {}, result });
165:           messages.push({ role: 'tool', tool_call_id: call.id, content: result });
166:         }
167:         continue;
168:       }
169:       // Keep the answer before anything can reject it. A run that answered without investigating
170:       // at all was rejected here and its answer was lost, which is the failure failed-run.json
171:       // exists to prevent; the preservation path only triggered once this had already been set.
172:       attempt.answer = message.content;
173:       if (!researched()) {
174:         throw new Error('The model proposed a graph without reading repository evidence.');
175:       }
176:       // Seven of ten citations in one run named files the run never opened, one of them a file that
177:       // does not exist. Asking for honest citations has not worked, and repairing them would be
178:       // repair; a citation is checkable against the transcript, so it is checked.
179:       const opened = new Set(investigation
180:         .filter(item => item.tool === 'read_file' && /^\d+: /.test(item.result))
181:         .map(item => item.arguments.path));
182:       // A complete, otherwise valid graph was once discarded because the model wrapped it in a
183:       // markdown fence. Removing that envelope is not JSON repair: malformed JSON inside it,
184:       // a drifted objective or an invalid graph are still rejected exactly as before.
185:       const fenced = message.content.trim().match(/^```[a-z]*\s*\n([\s\S]*?)\n?```$/i);
