189:       } catch (error) {
190:         throw new Error(`Invalid planner graph: ${error.message}. No repair or retry was made.`);
191:       }
192:       const invented = graph.nodes.flatMap(node =>
193:         node.evidence.filter(item => !opened.has(cited(item))).map(item => `${node.id}: ${item}`));
194:       if (invented.length) {
195:         throw new Error(`The graph cites ${invented.length} file(s) this run never read:\n${invented.join('\n')}\nNo repair or retry was made.`);
196:       }
197:       graph.run = { model: MODEL, createdAt: attempt.createdAt, requests: turn, costUsd: attempt.costUsd, priorGraph: attempt.priorGraph, investigation };
198:       const html = renderGraph(graph);
199:       keep = true;
200:       await writeFile(join(output, 'graph.json'), JSON.stringify(graph, null, 2) + '\n', { flag: 'wx', mode: 0o600 });
201:       await writeFile(join(output, 'graph.html'), html, { flag: 'wx', mode: 0o600 });
202:       return join(output, 'graph.html');
203:     }
204:     throw new Error('Investigation limit reached. No graph saved.');
205:   } catch (error) {
206:     if (!attempt.investigation.length && attempt.answer === undefined) throw error;
207:     // Without this the run's transcript and rejected answer are lost and the failure cannot be diagnosed.
208:     const record = { objective, failure: error.message, run: attempt };
209:     try {
210:       await writeFile(join(output, 'failed-run.json'), JSON.stringify(record, null, 2) + '\n', { flag: 'wx', mode: 0o600 });
